(4791489, 693129, 81885, '<td valign="top">Great colours and tones.</td>', 'Great colours and tones.', '2008-06-30 10:51:17.000000', NULL, 1),
(4791570, 693280, 30049, '<td valign="top">Cute idea.  Food for thought for next time...use a circular polarizer to eliminate the reflection on the glass of the lightbulb, and either set your custom white balance to your shooting environment or adjust the color temp in post-processing.  All JMO of course.  :-)  Good luck in the challenge.</td>', 'Cute idea.  Food for thought for next time...use a circular polarizer to eliminate the reflection on the glass of the lightbulb, and either set your custom white balance to your shooting environment or adjust the color temp in post-processing.  All JMO of course.  :-)  Good luck in the challenge.', '2008-06-30 11:59:57.000000', NULL, 1),
(4791573, 693325, 30049, '<td valign="top">???  Sorry, but I don''t get it.  Is this a mistake, meant to be in the upcoming free study perhaps?</td>', '???  Sorry, but I don''t get it.  Is this a mistake, meant to be in the upcoming free study perhaps?', '2008-06-30 12:04:41.000000', NULL, 1),
(4791591, 693214, 30049, '<td valign="top">Great idea...the money is a distraction and probably wasn''t needed.  Good luck.</td>', 'Great idea...the money is a distraction and probably wasn''t needed.  Good luck.', '2008-06-30 12:19:30.000000', NULL, 1),
