(4792422, 693325, 14369, '<td valign="top">????</td>', '????', '2008-06-30 21:28:23.000000', NULL, 1),
(4792720, 692949, 81362, '<td valign="top">Nice graphic simplicity and sharp focus on the filament. Diagonal orientation seems appropriate. I like the yellow-orange and blue, which have associations with light bulbs I have seen. The green is an acceptable artistic choice, but I would have liked less of the green arc, mostly because of my own bias and experience. Nevertheless, one of the higher scores from me.</td>', 'Nice graphic simplicity and sharp focus on the filament. Diagonal orientation seems appropriate. I like the yellow-orange and blue, which have associations with light bulbs I have seen. The green is an acceptable artistic choice, but I would have liked less of the green arc, mostly because of my own bias and experience. Nevertheless, one of the higher scores from me.', '2008-07-01 00:28:01.000000', NULL, 1),
(4792725, 693310, 81362, '<td valign="top">Nicely exposed, but the glass edges get lost in the swirls of fur. I find the black bands at the right and left sides a little too wide.</td>', 'Nicely exposed, but the glass edges get lost in the swirls of fur. I find the black bands at the right and left sides a little too wide.', '2008-07-01 00:29:41.000000', NULL, 1),
(4792728, 692794, 81362, '<td valign="top">Unusual combination makes me want to know if there is something that ties the objects together. Nice lighting of the objects and shadow beneath the platter, but to my taste the upper third of the image might be nicer a little lighter.</td>', 'Unusual combination makes me want to know if there is something that ties the objects together. Nice lighting of the objects and shadow beneath the platter, but to my taste the upper third of the image might be nicer a little lighter.', '2008-07-01 00:30:16.000000', NULL, 1),
(4792731, 693170, 81362, '<td valign="top">Love the sense of humor. I suppose anyone giving this a very low score would have to belong to the group of twisted critics illustrated here.</td>', 'Love the sense of humor. I suppose anyone giving this a very low score would have to belong to the group of twisted critics illustrated here.', '2008-07-01 00:31:18.000000', NULL, 1),
