(4795716, 693297, 70794, '<td valign="top">Wow    nice  idea</td>', 'Wow    nice  idea', '2008-07-01 19:32:13.000000', NULL, 1),
(4796535, 693175, 93565, '<td valign="top">I rather like the extreme saturations of the colors on this. The dark pavement, the vibrant red lights, and the light sky all combine nicely. Also like how the tunnel provided almost a natural vignette.</td>', 'I rather like the extreme saturations of the colors on this. The dark pavement, the vibrant red lights, and the light sky all combine nicely. Also like how the tunnel provided almost a natural vignette.', '2008-07-02 00:15:25.000000', NULL, 1),
(4796540, 693082, 93565, '<td valign="top">I like this as an abstract shot, but wasn''t quite what I was expecting for this particular challenge.</td>', 'I like this as an abstract shot, but wasn''t quite what I was expecting for this particular challenge.', '2008-07-02 00:17:15.000000', NULL, 1),
(4796560, 693197, 93565, '<td valign="top">The sepia treatment works well for the subject matter. I think the shot could be improved a little by expanding DoF to include the front pieces more since the majority is relatively focused.</td>', 'The sepia treatment works well for the subject matter. I think the shot could be improved a little by expanding DoF to include the front pieces more since the majority is relatively focused.', '2008-07-02 00:24:29.000000', NULL, 1),
(4796567, 692788, 93565, '<td valign="top">I really like this one- the bulb is reminiscent of the moon peaking around a dense cloud or something of the sort. The border adds a lot as well.</td>', 'I really like this one- the bulb is reminiscent of the moon peaking around a dense cloud or something of the sort. The border adds a lot as well.', '2008-07-02 00:26:29.000000', NULL, 1),
(4796573, 693105, 93565, '<td valign="top">I think this shot would benefit from sharper focus. The red lighting is great!</td>', 'I think this shot would benefit from sharper focus. The red lighting is great!', '2008-07-02 00:28:20.000000', NULL, 1),
(4796576, 693114, 93565, '<td valign="top">Good job taking an ordinary, everyday object and making it more interesting. The black bulb is definitely cool.</td>', 'Good job taking an ordinary, everyday object and making it more interesting. The black bulb is definitely cool.', '2008-07-02 00:29:46.000000', NULL, 1),
(4796586, 693307, 93565, '<td valign="top">I think the brown background works well with this (better than I feel black would) but the mottling effect is somewhat distracting.</td>', 'I think the brown background works well with this (better than I feel black would) but the mottling effect is somewhat distracting.', '2008-07-02 00:32:07.000000', NULL, 1),
(4796608, 693189, 93565, '<td valign="top">Seems too harsly lit for my tastes.</td>', 'Seems too harsly lit for my tastes.', '2008-07-02 00:37:26.000000', NULL, 1),
(4796636, 693036, 93565, '<td valign="top">Very strange, but also very cool looking.</td>', 'Very strange, but also very cool looking.', '2008-07-02 00:42:47.000000', NULL, 1),
(4796651, 692756, 93565, '<td valign="top">Very neat use of macro. The ghosted filaments look very cool.</td>', 'Very neat use of macro. The ghosted filaments look very cool.', '2008-07-02 00:46:12.000000', NULL, 1),
(4796660, 693005, 93565, '<td valign="top">Really cool reflection shot. The only bummer is how apparent the photographer is.</td>', 'Really cool reflection shot. The only bummer is how apparent the photographer is.', '2008-07-02 00:47:45.000000', NULL, 1),
(4796673, 692860, 93565, '<td valign="top">I really like the repetition, and especially how the "walls" constrain things at the focal point.</td>', 'I really like the repetition, and especially how the "walls" constrain things at the focal point.', '2008-07-02 00:51:13.000000', NULL, 1),
(4796684, 693092, 93565, '<td valign="top">Good idea for the shot. I think this could have been enhanced greatly by figuring a way of keeping the rigging out of the shot.</td>', 'Good idea for the shot. I think this could have been enhanced greatly by figuring a way of keeping the rigging out of the shot.', '2008-07-02 00:53:48.000000', NULL, 1),
(4796704, 693112, 93565, '<td valign="top">The the contrast between each concentric spiral''s color is great.</td>', 'The the contrast between each concentric spiral''s color is great.', '2008-07-02 00:57:23.000000', NULL, 1),
(4796711, 692755, 93565, '<td valign="top">Excellent concept photo. I like the silhouette and also the addition of color to the background.</td>', 'Excellent concept photo. I like the silhouette and also the addition of color to the background.', '2008-07-02 00:59:15.000000', NULL, 1),
(4796735, 693129, 93565, '<td valign="top">I can''t get over the colors of this. The texture on the hand is awesome and the reflections incredible.</td>', 'I can''t get over the colors of this. The texture on the hand is awesome and the reflections incredible.', '2008-07-02 01:04:40.000000', NULL, 1),
(4796743, 693136, 93565, '<td valign="top">I really like this- the flowers fit perfectly. My only complaint is that you can see some of the flowers in the lower right background.</td>', 'I really like this- the flowers fit perfectly. My only complaint is that you can see some of the flowers in the lower right background.', '2008-07-02 01:05:41.000000', NULL, 1),
(4796956, 693092, 19708, '<td valign="top">Very interesting image here. I find it interesting that the other image in the green challenge is exact same title, exact same pic.</td>', 'Very interesting image here. I find it interesting that the other image in the green challenge is exact same title, exact same pic.', '2008-07-02 02:09:35.000000', NULL, 1),
(4797090, 693287, 79721, '<td valign="top">Props for a VERY clever idea, but the photo is so bland.</td>', 'Props for a VERY clever idea, but the photo is so bland.', '2008-07-02 03:39:46.000000', NULL, 1),
