(4803831, 693197, 32872, '<td valign="top">Nicely done!!!!</td>', 'Nicely done!!!!', '2008-07-05 03:36:37.000000', NULL, 1),
(4804498, 693082, 76335, '<td valign="top">I like this, but I suspect it''s going to be lost on most voters; it''s more a study in color than anything about a lightbulb -- and it''s <i>very</i> abstract, always a win-lose proposition here. That said, the colors are processed beautifully. I might have adjusted the color balance as it''s a bit on the yellow side.</td>', 'I like this, but I suspect it''s going to be lost on most voters; it''s more a study in color than anything about a lightbulb -- and it''s very abstract, always a win-lose proposition here. That said, the colors are processed beautifully. I might have adjusted the color balance as it''s a bit on the yellow side.', '2008-07-05 12:37:07.000000', NULL, 1),
(4804505, 692990, 76335, '<td valign="top">Beautiful abstract with great colors. It''s a little off center -- don''t know if that could have been helped.</td>', 'Beautiful abstract with great colors. It''s a little off center -- don''t know if that could have been helped.', '2008-07-05 12:38:26.000000', NULL, 1),
(4804524, 692826, 76335, '<td valign="top">I think it''s "Chang<i>es</i>." Not a terribly well-inspired composition, and I think I see the camera in reflection.</td>', 'I think it''s "Changes." Not a terribly well-inspired composition, and I think I see the camera in reflection.', '2008-07-05 12:42:27.000000', NULL, 1),
(4804526, 693330, 76335, '<td valign="top">Great idea. Congrats not getting the camera in reflection (at least, not that I can see).</td>', 'Great idea. Congrats not getting the camera in reflection (at least, not that I can see).', '2008-07-05 12:43:07.000000', NULL, 1),
(4804540, 693244, 76335, '<td valign="top">What is that in the lower left?</td>', 'What is that in the lower left?', '2008-07-05 12:45:25.000000', NULL, 1),
(4804550, 693280, 76335, '<td valign="top">Skittles again?! Lighting''s a bit dull, but nice job overall.</td>', 'Skittles again?! Lighting''s a bit dull, but nice job overall.', '2008-07-05 12:47:11.000000', NULL, 1),
(4804561, 693325, 76335, '<td valign="top">Well, you know...</td>', 'Well, you know...', '2008-07-05 12:48:47.000000', NULL, 1),
(4804567, 693312, 76335, '<td valign="top">Holy crap, how''d you do that?! Would like to have seen better focus on the bulb, but great job capturing this by <i>any</i> means.</td>', 'Holy crap, how''d you do that?! Would like to have seen better focus on the bulb, but great job capturing this by any means.', '2008-07-05 12:50:06.000000', NULL, 1),
(4804571, 693287, 76335, '<td valign="top">Funny, but yuck.</td>', 'Funny, but yuck.', '2008-07-05 12:50:44.000000', NULL, 1),
(4804583, 692788, 76335, '<td valign="top">Abstract indeed. It''s a bit unlevel, and also would like to have seen the dark orange (above the yellow line) blend more with the black, making it less obvious just what this is.</td>', 'Abstract indeed. It''s a bit unlevel, and also would like to have seen the dark orange (above the yellow line) blend more with the black, making it less obvious just what this is.', '2008-07-05 12:53:09.000000', NULL, 1),
