(4804848, 692825, 76335, '<td valign="top">I like the simple, no frills presentation. It''s just a light bulb -- lit.</td>', 'I like the simple, no frills presentation. It''s just a light bulb -- lit.', '2008-07-05 14:10:36.000000', NULL, 1),
(4804853, 693269, 76335, '<td valign="top">I like the blue background, and the border seems to help isolate and enhance the composition.</td>', 'I like the blue background, and the border seems to help isolate and enhance the composition.', '2008-07-05 14:11:55.000000', NULL, 1),
(4804856, 693170, 76335, '<td valign="top">Funny idea, well executed.</td>', 'Funny idea, well executed.', '2008-07-05 14:12:54.000000', NULL, 1),
