(4804865, 693306, 76335, '<td valign="top">Borders on psychadelic. Good job!</td>', 'Borders on psychadelic. Good job!', '2008-07-05 14:15:31.000000', NULL, 1),
(4804870, 693114, 76335, '<td valign="top">Good use of negative. A bit more contrast behind the bulb is needed.</td>', 'Good use of negative. A bit more contrast behind the bulb is needed.', '2008-07-05 14:16:20.000000', NULL, 1),
