(4804991, 693310, 76335, '<td valign="top">The composition itself doesn''t do much for me, but technically (lighting, focus, etc.) it''s a job well done.</td>', 'The composition itself doesn''t do much for me, but technically (lighting, focus, etc.) it''s a job well done.', '2008-07-05 15:23:32.000000', NULL, 1),
(4804994, 693238, 76335, '<td valign="top">Nice contrast and capture of textures. Likes you did this is a mild sepia which also works well.</td>', 'Nice contrast and capture of textures. Likes you did this is a mild sepia which also works well.', '2008-07-05 15:24:40.000000', NULL, 1),
(4804995, 693124, 76335, '<td valign="top">Clean and simple. I like the composition (is that a vice?).</td>', 'Clean and simple. I like the composition (is that a vice?).', '2008-07-05 15:25:48.000000', NULL, 1),
(4805000, 693106, 76335, '<td valign="top">Compositionally, it''s a bit busy (the wall/ceiling is distracting) and it looks like a color balance adjustment might have cured the yellow cast. Of course it is a Light Bulb challenge, so maybe that''s the effect you were after. In that case, a tighter crop might have helped.</td>', 'Compositionally, it''s a bit busy (the wall/ceiling is distracting) and it looks like a color balance adjustment might have cured the yellow cast. Of course it is a Light Bulb challenge, so maybe that''s the effect you were after. In that case, a tighter crop might have helped.', '2008-07-05 15:29:16.000000', NULL, 1),
(4805002, 692995, 76335, '<td valign="top">I knew one of thse was coming. Nice job.</td>', 'I knew one of thse was coming. Nice job.', '2008-07-05 15:29:58.000000', NULL, 1),
(4805010, 692906, 76335, '<td valign="top">Abstract and interesting patterns of light and shadows. It has rhythm. I think cropping some or all of the bottom would have helped.</td>', 'Abstract and interesting patterns of light and shadows. It has rhythm. I think cropping some or all of the bottom would have helped.', '2008-07-05 15:32:22.000000', NULL, 1),
(4805013, 693036, 76335, '<td valign="top">Abstract and interesting. I wonder how this would have looked horizontal. In any case, I like the subtle colors and patterns you got our of this.</td>', 'Abstract and interesting. I wonder how this would have looked horizontal. In any case, I like the subtle colors and patterns you got our of this.', '2008-07-05 15:33:23.000000', NULL, 1),
(4805016, 692949, 76335, '<td valign="top">Great angle, excellent colors.</td>', 'Great angle, excellent colors.', '2008-07-05 15:34:21.000000', NULL, 1),
(4805036, 693175, 76335, '<td valign="top">I like this, though I''m sure you''re getting some DNMC''s. Hopefully not. Great colors and motion. I might have cropped off some of the left.</td>', 'I like this, though I''m sure you''re getting some DNMC''s. Hopefully not. Great colors and motion. I might have cropped off some of the left.', '2008-07-05 15:38:11.000000', NULL, 1),
(4805045, 692935, 76335, '<td valign="top">Simple but with impact. Good contrast and subtle textures.</td>', 'Simple but with impact. Good contrast and subtle textures.', '2008-07-05 15:40:49.000000', NULL, 1),
(4805171, 693185, 76335, '<td valign="top">Surreal and interesting. One of the more creative entries in the challenge. Good job composing and processing this.</td>', 'Surreal and interesting. One of the more creative entries in the challenge. Good job composing and processing this.', '2008-07-05 16:51:06.000000', NULL, 1),
(4805172, 693099, 76335, '<td valign="top">Charming. Great idea and well processed.</td>', 'Charming. Great idea and well processed.', '2008-07-05 16:51:17.000000', NULL, 1),
(4805173, 692954, 76335, '<td valign="top">Beautifully crips focus, great compostion.</td>', 'Beautifully crips focus, great compostion.', '2008-07-05 16:51:21.000000', NULL, 1),
(4805175, 693169, 76335, '<td valign="top">Terrific concept and use of grain. This has a dark yet comic feel to it -- like something from an old movie. An eight for you.</td>', 'Terrific concept and use of grain. This has a dark yet comic feel to it -- like something from an old movie. An eight for you.', '2008-07-05 16:52:37.000000', NULL, 1),
