(4805179, 693120, 76335, '<td valign="top">Wow, I hope the fire station is close by. Anyway, great idea and <i>very</i> intriguing. A seven for you.</td>', 'Wow, I hope the fire station is close by. Anyway, great idea and very intriguing. A seven for you.', '2008-07-05 16:54:06.000000', NULL, 1),
(4805180, 693320, 76335, '<td valign="top">Simple, clean, abstract, great message. A seven for you.</td>', 'Simple, clean, abstract, great message. A seven for you.', '2008-07-05 16:54:16.000000', NULL, 1),
