(4805182, 693260, 76335, '<td valign="top">Abstract and interesting. Great job capturing this -- just the right exposure and focus to bring out all the interesting imperfections. An eight for you.</td>', 'Abstract and interesting. Great job capturing this -- just the right exposure and focus to bring out all the interesting imperfections. An eight for you.', '2008-07-05 16:54:43.000000', NULL, 1),
