(4808564, 692954, 18450, '<td valign="top">Beautiful lighting, colours and composition. Congrats Irene (((hugs)))</td>', 'Beautiful lighting, colours and composition. Congrats Irene (((hugs)))', '2008-07-07 04:18:28.000000', NULL, 0),
