(4809350, 693005, 24454, '<td valign="top">Oh, Michelle!  CONGRATULATIONS!   I''m so happy for your winning a ribbon!    This is amazing photography!<br/> <br/></td>', 'Oh, Michelle!  CONGRATULATIONS!   I''m so happy for your winning a ribbon!    This is amazing photography! ', '2008-07-07 15:11:19.000000', NULL, 0),
(4809356, 693129, 24454, '<td valign="top">Fun indeed  :)   Made even more fun winning a ribbon, huh?   CONGRATULATIONS!  This is great!<br/> <br/></td>', 'Fun indeed  :)   Made even more fun winning a ribbon, huh?   CONGRATULATIONS!  This is great! ', '2008-07-07 15:13:28.000000', NULL, 0),
(4809358, 692954, 24454, '<td valign="top">I think they should start making it official that from now on, only 2 ribbons are awarded and the third one automatically goes to you :)  CONGRATULATIONS once again, Irene!   Exquisite work as always!<br/> <br/></td>', 'I think they should start making it official that from now on, only 2 ribbons are awarded and the third one automatically goes to you :)  CONGRATULATIONS once again, Irene!   Exquisite work as always! ', '2008-07-07 15:15:15.000000', NULL, 0),
(4809365, 693099, 24454, '<td valign="top">Awwwwww, Lydia!  This is so cute!   I truly love frogs, and I''m always so amazed when people can get them to sit still long enough to get these adorable shots!   Congratulations on an honorable mention for this one!<br/> <br/>If it had been me picking, this one would have a ribbon under it!<br/> <br/></td>', 'Awwwwww, Lydia!  This is so cute!   I truly love frogs, and I''m always so amazed when people can get them to sit still long enough to get these adorable shots!   Congratulations on an honorable mention for this one! If it had been me picking, this one would have a ribbon under it! ', '2008-07-07 15:17:58.000000', NULL, 0),
